+.cart-count{position:absolute;top:4px;right:2px;background:var(--gold);color:#111;
+  font-size:10px;font-weight:700;border-radius:999px;min-width:16px;height:16px;
+  display:grid;place-items:center;padding:0 4px;transition:.2s;transform:scale(.6);opacity:0}
+.cart-count.is-active{transform:scale(1);opacity:1}
+
+/* ---------- Hero ---------- */
+.hero{position:relative;overflow:hidden;border-bottom:1px solid var(--line)}
+.hero__bg{position:absolute;inset:0;z-index:0}
+.hero__orb{position:absolute;border-radius:50%;filter:blur(120px);opacity:.5}
+.hero__orb--a{width:520px;height:520px;background:radial-gradient(circle,#3b2d10,transparent 70%);top:-100px;right:-100px}
+.hero__orb--b{width:420px;height:420px;background:radial-gradient(circle,#1b2a3b,transparent 70%);bottom:-120px;left:10%}
+.hero__grid{position:absolute;inset:0;background-image:
+  linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),
+  linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);
+  background-size:80px 80px;mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%)}
+.hero__inner{position:relative;z-index:1;display:grid;grid-template-columns:1.2fr .9fr;gap:64px;
+  padding:96px 28px 110px;align-items:center}
+.hero__title{font-size:clamp(46px,7vw,96px);line-height:1;letter-spacing:-.025em;margin-bottom:28px}
+.hero__title span{display:block}
