.nav__inner{display:flex;align-items:center;justify-content:space-between;height:72px;gap:28px}
.nav__menu{display:none;flex-direction:column;gap:4px;width:24px;height:24px;justify-content:center}
.nav__menu span{height:1.5px;background:var(--text);width:100%;transition:.25s}
.brand{display:flex;align-items:center;gap:10px;font-family:var(--serif);font-size:18px;font-weight:700;letter-spacing:.02em}
.brand__mark{color:var(--gold);font-size:22px;line-height:1}
