.nav__links a{position:relative;transition:.2s}
.nav__links a:hover{color:var(--text)}
.nav__links a::after{content:"";position:absolute;left:0;right:0;bottom:-22px;height:1px;
  background:var(--gold);transform:scaleX(0);transform-origin:left;transition:.25s}
.nav__links a:hover::after{transform:scaleX(1)}
.nav__icons{display:flex;gap:6px;align-items:center}
.icon-btn{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;color:var(--text-2);transition:.2s;position:relative}
.icon-btn:hover{background:var(--bg-2);color:var(--text)}
.cart-count{position:absolute;top:4px;right:2px;background:var(--gold);color:#111;
  font-size:10px;font-weight:700;border-radius:999px;min-width:16px;height:16px;
  display:grid;place-items:center;padding:0 4px;transition:.2s;transform:scale(.6);opacity:0}
.cart-count.is-active{transform:scale(1);opacity:1}

/* ---------- Hero ---------- */
.hero{position:relative;overflow:hidden;border-bottom:1px solid var(--line)}
.hero__bg{position:absolute;inset:0;z-index:0}
.hero__orb{position:absolute;border-radius:50%;filter:blur(120px);opacity:.5}
