.hero__grid{position:absolute;inset:0;background-image:
  linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),
  linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);
  background-size:80px 80px;mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%)}
.hero__inner{position:relative;z-index:1;display:grid;grid-template-columns:1.2fr .9fr;gap:64px;
  padding:96px 28px 110px;align-items:center}
.hero__title{font-size:clamp(46px,7vw,96px);line-height:1;letter-spacing:-.025em;margin-bottom:28px}
.hero__title span{display:block}
.hero__title .ital{font-style:italic;font-weight:400;color:var(--text-2)}
.hero__title .hl{background:linear-gradient(120deg,var(--gold-2),var(--gold) 60%,#8a6d35);
  -webkit-background-clip:text;background-clip:text;color:transparent}
.hero__lede{font-size:17px;color:var(--text-2);max-width:520px;margin-bottom:36px}
.hero__cta{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:54px}
.hero__meta{display:flex;gap:36px;border-top:1px solid var(--line);padding-top:24px;max-width:520px}
.hero__meta li{display:flex;flex-direction:column;gap:2px}
.hero__meta strong{font-family:var(--serif);font-size:24px;font-weight:600}
.hero__meta span{font-size:12px;color:var(--text-3);letter-spacing:.08em;text-transform:uppercase}

.hero__card{background:linear-gradient(180deg,var(--bg-2),var(--bg-1));
  border:1px solid var(--line);border-radius:var(--radius-lg);overflow:hidden;
  box-shadow:var(--shadow);transform:rotate(1.2deg);transition:transform .5s}
.hero__card:hover{transform:rotate(0deg) translateY(-4px)}
.hero__card-img{aspect-ratio:4/5;position:relative;overflow:hidden}
.badge{position:absolute;top:16px;left:16px;background:rgba(0,0,0,.55);backdrop-filter:blur(8px);
