+.ph::before,.ph::after{content:"";position:absolute;border-radius:50%;filter:blur(40px);opacity:.6}
+.ph--coat{background:linear-gradient(160deg,#2b2418,#0d0a06)}
+.ph--coat::before{width:60%;height:60%;background:#5a4626;top:-10%;right:-10%}
+.ph--coat::after{width:50%;height:50%;background:#1a1207;bottom:-15%;left:-10%;filter:blur(30px);opacity:.9}
+.ph--studio{background:linear-gradient(160deg,#1d2433,#0a0e16)}
+.ph--studio::before{width:60%;height:60%;background:#3b537e;top:-15%;left:-10%}
+.ph--studio::after{width:55%;height:55%;background:#0e1729;bottom:-20%;right:-15%;filter:blur(30px)}
+.ph--mug{background:linear-gradient(160deg,#241f1a,#0d0a08)}
+.ph--mug::before{width:70%;height:70%;background:#6b5742;top:0;left:15%}
+.ph--bag{background:linear-gradient(160deg,#1f1c14,#0a0805)}
+.ph--bag::before{width:80%;height:55%;background:#4a3c20;bottom:-10%;left:10%;border-radius:30%}
+.ph--candle{background:linear-gradient(160deg,#191c1a,#080a09)}
+.ph--candle::before{width:30%;height:75%;background:#c9a46a;top:8%;left:35%;border-radius:6px;filter:blur(8px)}
+.ph--candle::after{width:8%;height:18%;background:#ffd47a;top:-2%;left:46%;filter:blur(14px);opacity:1}
+
+.ph--ed1{background:linear-gradient(160deg,#1a1f1c,#080b09)}
+.ph--ed1::before{width:80%;height:80%;background:#3a5b4a;top:-20%;right:-20%}
+.ph--ed1::after{width:50%;height:50%;background:#0c1410;bottom:-10%;left:0;filter:blur(20px)}
+.ph--ed2{background:linear-gradient(160deg,#231a1a,#0c0707)}
+.ph--ed2::before{width:70%;height:70%;background:#6b3a3a;top:-10%;left:-10%}
+.ph--ed3{background:linear-gradient(160deg,#1a1922,#08070d)}
+.ph--ed3::before{width:65%;height:65%;background:#3d3554;top:-5%;right:-15%}
+.ph--ed4{background:linear-gradient(160deg,#22201a,#0c0a07)}
+.ph--ed4::before{width:75%;height:60%;background:#7a6433;bottom:-20%;left:-10%}
+
+/* product placeholders (varied palettes) */
+.ph--p1{background:linear-gradient(160deg,#2a2418,#0e0c08)}
+.ph--p1::before{width:65%;height:80%;background:#604a2a;top:-5%;left:15%;border-radius:35% 35% 10% 10%}
+.ph--p2{background:linear-gradient(160deg,#1a1d24,#08090c)}
+.ph--p2::before{width:55%;height:70%;background:#39496b;top:5%;left:22%;border-radius:40% 40% 8% 8%}
+.ph--p3{background:linear-gradient(160deg,#231f1d,#0c0908)}
+.ph--p3::before{width:70%;height:50%;background:#5e463a;bottom:-5%;left:15%;border-radius:50% 50% 0 0}
+.ph--p4{background:linear-gradient(160deg,#1d231f,#08100a)}
+.ph--p4::before{width:60%;height:60%;background:#3a5d44;top:10%;left:20%;border-radius:50%}
+.ph--p5{background:linear-gradient(160deg,#221c24,#0a070b)}
+.ph--p5::before{width:50%;height:75%;background:#5a3f64;top:5%;left:25%;border-radius:30%}
+.ph--p6{background:linear-gradient(160deg,#241e1a,#0c0908)}
+.ph--p6::before{width:80%;height:45%;background:#765538;bottom:5%;left:10%;border-radius:18px}
+.ph--p7{background:linear-gradient(160deg,#1c1f23,#08090c)}
+.ph--p7::before{width:55%;height:55%;background:#4a596d;top:18%;left:22%;border-radius:50%}
+.ph--p8{background:linear-gradient(160deg,#252118,#0c0a07)}
+.ph--p8::before{width:70%;height:70%;background:#7a623a;top:-10%;left:15%;border-radius:0 0 40% 40%}
+
+.ph--lg::before,.ph--lg::after{filter:blur(60px)}
+
+/* ---------- Categories strip ---------- */
+.cats{border-bottom:1px solid var(--line)}
+.cats__grid{display:grid;grid-template-columns:repeat(5,1fr)}
+.cat{display:flex;align-items:center;justify-content:space-between;gap:14px;
+  padding:34px 24px;border-right:1px solid var(--line);transition:.3s;position:relative;overflow:hidden}
+.cat:last-child{border-right:0}
+.cat::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent,rgba(216,180,106,.06));
+  opacity:0;transition:.3s}
+.cat:hover::before{opacity:1}
+.cat__num{font-family:var(--serif);font-style:italic;color:var(--text-3);font-size:14px}
+.cat__name{font-family:var(--serif);font-size:22px;flex:1}
+.cat__arrow{color:var(--text-3);transition:.3s}
+.cat:hover .cat__arrow{color:var(--gold);transform:translate(4px,-4px)}
+
+/* ---------- Section ---------- */
+.section{padding:110px 0}
+.section__head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:54px;flex-wrap:wrap}
+
+/* ---------- Filters ---------- */
+.filters{display:flex;gap:8px;flex-wrap:wrap}
+.chip{padding:10px 18px;border-radius:999px;border:1px solid var(--line-2);
+  font-size:13px;color:var(--text-2);transition:.2s}
+.chip:hover{color:var(--text);border-color:var(--text-3)}
+.chip.is-active{background:var(--text);color:#111;border-color:var(--text)}
+
+/* ---------- Product grid ---------- */
+.grid--products{display:grid;grid-template-columns:repeat(4,1fr);gap:28px 22px}
+.product{position:relative;display:flex;flex-direction:column;gap:14px;cursor:pointer;
+  transition:transform .35s;will-change:transform}
+.product:hover{transform:translateY(-4px)}
+.product__media{position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;
+  background:var(--bg-2);border:1px solid var(--line)}
+.product__media .ph{transition:transform .8s ease}
+.product:hover .ph{transform:scale(1.05)}
+.product__overlay{position:absolute;inset:auto 12px 12px;display:flex;gap:8px;
+  opacity:0;transform:translateY(8px);transition:.3s}
+.product:hover .product__overlay{opacity:1;transform:translateY(0)}
+.product__overlay .btn{flex:1;background:rgba(15,15,20,.85);backdrop-filter:blur(10px);
+  color:var(--text);border:1px solid var(--line-2);padding:12px}
+.product__overlay .btn:hover{background:var(--accent);color:#111;border-color:var(--accent)}
+.product__icon{width:42px;height:42px;flex:0 0 42px;background:rgba(15,15,20,.85);
+  border:1px solid var(--line-2);border-radius:50%;display:grid;place-items:center;color:var(--text);
+  backdrop-filter:blur(10px);transition:.2s}
+.product__icon:hover{background:var(--bg-3);color:var(--gold)}
+.product__tag{position:absolute;top:12px;right:12px;background:var(--bg);color:var(--text);
+  padding:5px 10px;border-radius:999px;font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;
+  border:1px solid var(--line-2)}
+.product__tag--new{background:var(--gold);color:#111;border-color:transparent}
+.product__tag--low{background:#3a1d1d;color:#ffb4b4;border-color:#5a2a2a}
+.product__info{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}
+.product__name{font-size:15px;font-weight:500;line-height:1.3;margin-bottom:4px}
+.product__cat{font-size:11px;color:var(--text-3);letter-spacing:.12em;text-transform:uppercase}
+.product__price{font-family:var(--serif);font-size:17px;font-weight:600;white-space:nowrap}
+.product__price--old{color:var(--text-3);text-decoration:line-through;font-weight:400;font-size:13px;margin-left:6px}
+.product__swatches{display:flex;gap:5px;margin-top:2px}
+.product__swatches span{width:11px;height:11px;border-radius:50%;border:1px solid var(--line-2)}
+
+/* ---------- Deals ---------- */
+.deals{background:linear-gradient(180deg,var(--bg-1),var(--bg));padding:100px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
+.deals__head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:48px;flex-wrap:wrap}
+#countdown{color:var(--gold);font-size:.85em;font-weight:600;font-family:var(--sans);letter-spacing:.04em;
+  background:rgba(216,180,106,.1);padding:4px 10px;border-radius:6px;margin-left:6px;border:1px solid rgba(216,180,106,.25)}
+.deals__grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;grid-template-rows:auto auto;gap:22px}
+.deal{position:relative;background:var(--bg-2);border:1px solid var(--line);border-radius:var(--radius-lg);
+  overflow:hidden;display:flex;flex-direction:column;transition:.3s}
+.deal:hover{border-color:var(--line-2);transform:translateY(-3px)}
+.deal__media{position:relative;aspect-ratio:4/3;overflow:hidden}
+.deal--lg{grid-row:span 2;flex-direction:column}
+.deal--lg .deal__media{aspect-ratio:5/4}
+.deal__body{padding:22px;display:flex;flex-direction:column;gap:10px;flex:1}
+.deal__body .badge{position:static;align-self:flex-start;background:var(--gold);color:#111;border-color:transparent}
+.deal__body p{color:var(--text-2);font-size:14px}
+.deal__price{display:flex;align-items:baseline;gap:10px;margin-top:auto;padding-top:8px}
+.price{font-family:var(--serif);font-size:24px;font-weight:600}
+.price--old{color:var(--text-3);text-decoration:line-through;font-size:14px}
+.deal--lg .deal__body{padding:28px}
+.deal--lg .deal__body .btn{margin-top:14px;align-self:flex-start}
+
+/* ---------- Editorial ---------- */
+.editorial{background:var(--bg-1);border-top:1px solid var(--line)}
+.ed__grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:22px}
+.ed{display:flex;flex-direction:column;background:var(--bg-2);border:1px solid var(--line);
+  border-radius:var(--radius-lg);overflow:hidden;transition:.3s}
+.ed:hover{border-color:var(--line-2);transform:translateY(-3px)}
+.ed--feature{grid-row:span 2;grid-column:1}
+.ed--feature .ed__media{aspect-ratio:5/4}
+.ed__media{position:relative;aspect-ratio:4/3;overflow:hidden}
+.ed__media .ph{transition:transform .9s}
+.ed:hover .ph{transform:scale(1.04)}
+.ed__body{padding:22px;display:flex;flex-direction:column;gap:10px;flex:1}
+.ed--feature .ed__body{padding:36px;gap:14px}
+.ed--feature .ed__body h3{font-size:32px;line-height:1.1}
+.ed__tag{font-size:11px;color:var(--text-3);letter-spacing:.16em;text-transform:uppercase}
+.ed h4{font-family:var(--serif);font-size:18px;font-weight:600}
+.ed--feature p{color:var(--text-2);font-size:15px;max-width:480px}
+
+/* ---------- Values ---------- */
+.values{padding:60px 0;border-top:1px solid var(--line)}
+.values__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
+.value{padding:30px 28px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:10px;color:var(--gold)}
+.value:last-child{border-right:0}
+.value h5{color:var(--text)}
+.value p{color:var(--text-2);font-size:13px}
+
+/* ---------- Newsletter ---------- */
+.news{padding:110px 0;border-top:1px solid var(--line);background:
+  radial-gradient(ellipse at 80% 20%,rgba(216,180,106,.08),transparent 60%),var(--bg)}
+.news__inner{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
+.news h2{margin-bottom:14px}
+.news p{color:var(--text-2)}
+.news__form{display:flex;gap:10px;flex-wrap:wrap;position:relative}
+.news__form input{flex:1;min-width:240px;background:var(--bg-2);border:1px solid var(--line-2);
+  color:var(--text);padding:14px 20px;border-radius:999px;font:inherit;transition:.2s}
+.news__form input:focus{outline:none;border-color:var(--gold);background:var(--bg-3)}
+.news__msg{flex-basis:100%;font-size:13px;color:var(--green);min-height:18px;margin-top:4px}
+
+/* ---------- Footer ---------- */
+.footer{background:#050507;border-top:1px solid var(--line);padding:80px 0 30px;color:var(--text-2)}
+.footer__grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:48px;padding-bottom:60px;border-bottom:1px solid var(--line)}
+.footer__brand p{margin-top:18px;font-size:14px;max-width:300px}
+.footer ul{display:flex;flex-direction:column;gap:10px}
+.footer ul a{font-size:14px;color:var(--text-2);transition:.2s}
+.footer ul a:hover{color:var(--gold)}
+.footer__bottom{display:flex;justify-content:space-between;align-items:center;padding-top:30px;font-size:12px;color:var(--text-3);flex-wrap:wrap;gap:16px}
+.footer__pay{display:flex;gap:14px;font-size:10px;letter-spacing:.18em;color:var(--text-3)}
+
+/* ---------- Toast ---------- */
+.toast{position:fixed;bottom:30px;left:50%;transform:translate(-50%,30px);
+  background:var(--bg-3);border:1px solid var(--line-2);color:var(--text);padding:14px 22px;
+  border-radius:999px;font-size:14px;opacity:0;pointer-events:none;transition:.35s;z-index:100;
+  box-shadow:0 20px 50px -10px rgba(0,0,0,.7)}
+.toast.is-visible{opacity:1;transform:translate(-50%,0)}
+.toast strong{color:var(--gold);font-weight:600}
+
+/* ---------- Reveal ---------- */
+.reveal{opacity:0;transform:translateY(28px);transition:opacity .7s ease, transform .7s ease}
+.reveal.is-in{opacity:1;transform:none}
+
+/* ---------- Responsive ---------- */
+@media (max-width:1024px){
+  .hero__inner{grid-template-columns:1fr;padding:72px 28px 80px}
+  .hero__card{max-width:380px;justify-self:start}
+  .grid--products{grid-template-columns:repeat(3,1fr)}
+  .deals__grid{grid-template-columns:1fr 1fr}
+  .deal--lg{grid-row:span 1;grid-column:span 2}
+  .ed__grid{grid-template-columns:1fr 1fr}
+  .ed--feature{grid-row:span 1;grid-column:span 2}
+  .values__grid{grid-template-columns:1fr 1fr}
+  .value:nth-child(2){border-right:0}
+  .value{border-bottom:1px solid var(--line)}
+  .cats__grid{grid-template-columns:repeat(2,1fr)}
+  .cat{border-bottom:1px solid var(--line)}
+  .cat:nth-child(2n){border-right:0}
+}
+@media (max-width:720px){
+  .container{padding:0 20px}
+  .nav__links{display:none}
+  .nav__menu{display:flex}
+  .section{padding:72px 0}
+  .deals,.news{padding:72px 0}
+  .grid--products{grid-template-columns:repeat(2,1fr);gap:22px 14px}
+  .deals__grid{grid-template-columns:1fr}
+  .deal--lg{grid-column:span 1}
+  .ed__grid{grid-template-columns:1fr}
+  .ed--feature{grid-column:span 1}
+  .news__inner{grid-template-columns:1fr;gap:32px}
+  .footer__grid{grid-template-columns:1fr 1fr;gap:32px}
+  .values__grid{grid-template-columns:1fr}
+  .value{border-right:0;border-bottom:1px solid var(--line)}
+  .cats__grid{grid-template-columns:1fr}
+  .cat{border-right:0;border-bottom:1px solid var(--line)}
+  .hero__meta{gap:20px}
+  .hero__title{font-size:54px}
+}
+
')

