/* NOIR&CO — home page interactions */
(() => {
  const $ = (s, c=document) => c.querySelector(s);
  const $$ = (s, c=document) => [...c.querySelectorAll(s)];

  /* ---------- Products data ---------- */
  const products = [
    {id:1, name:"The Penumbra Coat",     cat:"apparel",  category:"Outerwear", price:486, ph:"ph--p1", swatches:["#3a2f1f","#1a1a1a","#5a4a32"], tag:"NEW",   isNew:true},
    {id:2, name:"Half-Light Knit",       cat:"apparel",  category:"Knitwear",  price:248, ph:"ph--p2", swatches:["#39496b","#2a2a2a","#8a7a5a"]},
    {id:3, name:"Field Tote, Waxed",     cat:"objects",  category:"Objects",   price:140, oldPrice:140, ph:"ph--p3", swatches:["#4a3826","#1c1c1c"], tag:"LOW STOCK", lowStock:true},
    {id:4, name:"Atelier Wool Trouser",  cat:"apparel",  category:"Trousers",  price:284, ph:"ph--p4", swatches:["#1a1a1a","#3a3a3a","#5a5a5a"]},
    {id:5, name:"Onyx Derby",            cat:"footwear", category:"Footwear",  price:398, ph:"ph--p5", swatches:["#1a1a1a","#3a2618"]},
    {id:6, name:"Stoneware Cup, Set 2",  cat:"objects",  category:"Objects",   price:48,  ph:"ph--p6", swatches:["#7a5a3a","#2a2a2a"]},
    {id:7, name:"Eclipse Overshirt",     cat:"apparel",  category:"Shirts",    price:212, ph:"ph--p7", swatches:["#2a3346","#1a1a1a","#4a5a3a"], tag:"NEW", isNew:true},
    {id:8, name:"Mohair Crew, Sand",     cat:"apparel",  category:"Knitwear",  price:268, ph:"ph--p8", swatches:["#7a623a","#3a3022","#1a1a1a"]},
  ];

  /* ---------- Render products ---------- */
  const grid = $("#productGrid");
  const renderProducts = (filter="all") => {
    const items = filter==="all" ? products : products.filter(p=>p.cat===filter);
    grid.innerHTML = items.map(p => `
      <article class="product reveal" data-cat="${p.cat}">
        <div class="product__media">
          <div class="ph ${p.ph}"></div>
          ${p.isNew    ? `<span class="product__tag product__tag--new">New</span>` : ""}
          ${p.lowStock ? `<span class="product__tag product__tag--low">Low stock</span>` : ""}
          <div class="product__overlay">
            <button class="btn" data-add="${p.name}" data-price="${p.price}">Add to bag</button>
            <button class="product__icon" aria-label="Save ${p.name}">
              <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 1 0-7.8 7.8l1 1L12 21l7.8-7.6 1-1a5.5 5.5 0 0 0 0-7.8z"/></svg>
            </button>
          </div>
        </div>
        <div class="product__info">
          <div>
            <p class="product__cat">${p.category}</p>
            <h3 class="product__name">${p.name}</h3>
            <div class="product__swatches">${p.swatches.map(c=>`<span style="background:${c}"></span>`).join("")}</div>
          </div>
          <div class="product__price">
            $${p.price}
            ${p.oldPrice ? `<span class="product__price--old">$${p.oldPrice}</span>` : ""}
          </div>
        </div>
      </article>
    `).join("");
    observeReveals();
  };
  renderProducts();

  /* ---------- Filter chips ---------- */
  $$(".filters .chip").forEach(chip => {
    chip.addEventListener("click", () => {
      $$(".filters .chip").forEach(c => c.classList.remove("is-active"));
      chip.classList.add("is-active");
      renderProducts(chip.dataset.filter);
    });
  });

  /* ---------- Cart ---------- */
  let cart = [];
  const cartCount = $("#cartCount");
  const updateCart = () => {
    cartCount.textContent = cart.length;
    cartCount.classList.toggle("is-active", cart.length > 0);
  };
  document.addEventListener("click", e => {
    const btn = e.target.closest("[data-add]");
    if (!btn) return;
    e.preventDefault();
    const name = btn.dataset.add;
    const price = btn.dataset.price;
    cart.push({name, price});
    updateCart();
    showToast(`Added <strong>${name}</strong> — $${price}`);
  });

  $("#cartBtn").addEventListener("click", () => {
    if (cart.length === 0) return showToast("Your bag is empty");
    const total = cart.reduce((s,i)=>s+Number(i.price),0);
    showToast(`<strong>${cart.length}</strong> item${cart.length>1?"s":""} · $${total} subtotal`);
  });

  /* ---------- Toast ---------- */
  const toast = $("#toast");
  let toastT;
  const showToast = (html) => {
    toast.innerHTML = html;
    toast.classList.add("is-visible");
    clearTimeout(toastT);
    toastT = setTimeout(() => toast.classList.remove("is-visible"), 2400);
  };

  /* ---------- Sticky nav state ---------- */
  const nav = $("#nav");
  const onScroll = () => nav.classList.toggle("is-scrolled", window.scrollY > 12);
  window.addEventListener("scroll", onScroll, {passive:true});
  onScroll();

  /* ---------- Newsletter ---------- */
  $("#newsForm").addEventListener("submit", e => {
    e.preventDefault();
    const msg = $("#newsMsg");
    msg.textContent = "Welcome aboard. Check your inbox for a quiet hello.";
    e.target.querySelector("input").value = "";
  });

  /* ---------- Countdown ---------- */
  // Ends at next 00:00 UTC + 3 days from now (rolling)
  const end = new Date();
  end.setUTCHours(24,0,0,0);
  end.setUTCDate(end.getUTCDate() + 2); // 3-day rolling deal
  const cd = $("#countdown");
  const tick = () => {
    let d = end - new Date();
    if (d < 0) d = 0;
    const h = String(Math.floor(d/3.6e6)).padStart(2,"0");
    const m = String(Math.floor(d/6e4)%60).padStart(2,"0");
    const s = String(Math.floor(d/1e3)%60).padStart(2,"0");
    cd.textContent = `${h}:${m}:${s}`;
  };
  tick(); setInterval(tick, 1000);

  /* ---------- Reveal on scroll ---------- */
  let io;
  const observeReveals = () => {
    if (!("IntersectionObserver" in window)) {
      $$(".reveal").forEach(el => el.classList.add("is-in"));
      return;
    }
    if (!io) {
      io = new IntersectionObserver(entries => {
        entries.forEach(e => {
          if (e.isIntersecting) {
            e.target.classList.add("is-in");
            io.unobserve(e.target);
          }
        });
      }, {threshold: 0.12, rootMargin: "0px 0px -40px 0px"});
    }
    $$(".reveal:not(.is-in)").forEach(el => io.observe(el));
  };
  // mark sections
  $$(".section, .deals, .editorial, .values, .news, .cats, .hero__card").forEach(el => el.classList.add("reveal"));
  observeReveals();
})();

